INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 4, 'theory', 'Quiz: the first program, Node and values');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 0, 'What does the V8 engine do with frequently called functions?', '["Runs them with the interpreter only", "Translates them back into source text", "Compiles them on the fly into the processor''s machine code (JIT)", "Saves them to a file on disk"]', 2, 'The text is parsed into a tree, then into bytecode, and “hot” functions are compiled to machine code while the program runs.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 1, 'What happens with const user = { n: 1 }; user.n = 2;?', '["The field changes: const forbids only replacing the binding itself", "TypeError: assignment to a constant", "The object is copied", "user becomes immutable"]', 0, 'const fixes the binding of the name to the value, not the contents of the object: user = {} causes an error, while user.n = 2 does not.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 2, 'What is typeof null?', '["\"null\"", "\"undefined\"", "\"number\"", "\"object\""]', 3, 'This is a historical mistake in the language that is not fixed for the sake of compatibility; check for null with the comparison x === null.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 3, 'Why does 0.1 + 0.2 === 0.3 give false?', '["Because of an addition bug in the engine", "There is one number type — a 64-bit float, and 0.1 and 0.2 are not exact in binary", "Because 0.3 is a string", "Because the === operator compares string types"]', 1, 'All numbers are IEEE 754 double precision, like double in C; decimal fractions such as 0.1 are approximate in binary.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 4, 4, 'Which expression returns 0?', '["0 || 5", "'''' || 0 || 5", "null ?? 5", "0 ?? 5"]', 3, 'The ?? operator picks the right operand only for null and undefined, so 0 stays; || replaces any falsy value, including 0.');
